```c
void cyclic_shift_to_file (char **str, int n, char *fileName)
{
    int i;
    FILE *fptr = fopen(fileName, "w");
    if (!fptr)
        exit(1);
    for (i=1; i<n; i++)
    {
        fputc(i+'0', fptr);
        fputs(str[i]+1, fptr);
        fputc('\n', fptr);
    }
    fputc(n+'0', fptr);
    fputs(str[0]+1, fptr);
    fputc('\n', fptr);
    fclose(fptr);
}
```

